/* Generates the widget files that must never be hand-edited (roadmap 2.1, 2.2).
 *
 *   node tools/widget_gen.js           write every generated file
 *   node tools/widget_gen.js --check   exit 1, naming each path that differs from what would be written
 *
 * generate(root) -> { [relPath]: text }. Output is byte-stable: sorted keys, no dates.
 * Today: workers/shared/widget-rules.mjs and app/since-rules.js. Later tasks extend the map. */
'use strict';
const fs = require('fs');
const path = require('path');

function sortKeys(v) {
  if (Array.isArray(v)) return v.map(sortKeys);
  if (v && typeof v === 'object') { const o = {}; Object.keys(v).sort().forEach((k) => { o[k] = sortKeys(v[k]); }); return o; }
  return v;
}
const lit = (v) => JSON.stringify(sortKeys(v), null, 2);

const FN_NAMES = ['sinceAnchor', 'babyAnchors', 'healthOpen', 'isTwins', 'ageOf', 'monthMoments', 'sleepEventId', 'snapshotBaby'];

function generate(root) {
  const copy = JSON.parse(fs.readFileSync(path.join(root, 'docs/widgets/widget-copy.json'), 'utf8'));
  const body = fs.readFileSync(path.join(root, 'workers/shared/since-rules.mjs'), 'utf8');
  const consts = { RULES: copy.rules, DEFAULTS: copy.defaults, SNAPSHOT_VERSIONS: copy.snapshot.versions };

  const rulesMjs = '// GENERATED by tools/widget_gen.js from docs/widgets/widget-copy.json. Do not edit.\n'
    + Object.keys(consts).map((k) => 'export const ' + k + ' = ' + lit(consts[k]) + ';\n').join('');

  const moduleBody = body
    .replace(/^import .*\n/m, '')
    .replace(/^export \{[^}]*\};?\n/m, '')
    .replace(/^export (function|const|let)/gm, '$1')
    .replace(/^\n+/, '');
  const appStrings = {};
  Object.keys(copy.strings || {}).sort().forEach((k) => {
    if ((copy.strings[k].on || []).indexOf('app') >= 0) appStrings[k] = copy.strings[k].text;
  });
  const sinceJs = '// GENERATED by tools/widget_gen.js from workers/shared/since-rules.mjs and docs/widgets/widget-copy.json. Do not edit.\n'
    + '(function () {\n'
    + Object.keys(consts).map((k) => 'const ' + k + ' = ' + lit(consts[k]) + ';\n').join('')
    + moduleBody.replace(/\s*$/, '\n')
    + 'window.CubbySince = { ' + FN_NAMES.concat(['RULES', 'DEFAULTS', 'SNAPSHOT_VERSIONS']).join(', ') + ' };\n'
    + 'window.CubbyWidgetCopy = ' + lit(appStrings) + ';\n'
    + '})();\n';

  return { 'workers/shared/widget-rules.mjs': rulesMjs, 'app/since-rules.js': sinceJs };
}

module.exports = { generate };

if (require.main === module) {
  const root = path.join(__dirname, '..');
  const out = generate(root);
  if (process.argv.includes('--check')) {
    const bad = Object.keys(out).filter((p) => { try { return fs.readFileSync(path.join(root, p), 'utf8') !== out[p]; } catch (e) { return true; } });
    bad.forEach((p) => console.log('differs: ' + p));
    if (bad.length) { console.log('run: node tools/widget_gen.js'); process.exit(1); }
    console.log('widget_gen: generated files are current');
  } else {
    Object.keys(out).forEach((p) => { fs.writeFileSync(path.join(root, p), out[p]); console.log('wrote ' + p); });
  }
}
